window.AP_LEARNING=window.AP_LEARNING||{};
window.AP_LEARNING['lesson-7']={
  version:1,
  title:'The Skeletal System',
  chapter:7,
  duration:'70–90 minutes',
  outcomes:[
    'Explain how the skeleton supports movement, protection, blood-cell formation and mineral storage.',
    'Distinguish bone formation, growth and remodeling and identify the cells involved.',
    'Read the microscopic and gross anatomy of compact, spongy and long bone.',
    'Organize major bones into axial and appendicular divisions.',
    'Connect nutrition, hormones and mechanical load to bone maintenance without overclaiming.'
  ],
  modules:[
    {id:'living-bone',title:'Bone is living tissue',summary:'Begin with function, formation and continual remodeling.',moments:[
      {id:'l7-m1',title:'Five jobs of the skeleton',highYield:'The skeleton is not a passive frame: it supports, protects, moves, forms blood cells and stores minerals and fat.',teaching:[
        'Bones create a firm framework that supports softer tissues and shields organs such as the brain, spinal cord, heart and lungs. At joints, bones also act as levers. Skeletal muscles pull on those levers to create movement and help expand the thorax during breathing.',
        'Red marrow forms blood cells through hematopoiesis. Bone also stores calcium and phosphorus, while yellow marrow stores fat. These roles explain why skeletal health is linked to movement, circulation and mineral homeostasis rather than being an isolated topic.'
      ],keyPoints:['Support and protection are structural roles.','Bones and muscles work as lever-and-force partners.','Red marrow forms blood cells.','Bone is a regulated mineral reservoir.'],visual:{title:'Function map',kind:'hub',items:[{label:'Framework',detail:'Supports tissues and posture'},{label:'Shield',detail:'Protects vital organs'},{label:'Lever',detail:'Transmits muscular force'},{label:'Marrow',detail:'Forms blood cells or stores fat'},{label:'Reservoir',detail:'Stores calcium and phosphorus'}]},mnemonic:{title:'SPLeMB',cue:'Support · Protect · Levers · Marrow · Bank',explanation:'Think of bone as the body’s support-and-storage bank.'},goodToKnow:'The mineral matrix makes bone hard, but living cells, vessels and nerves make it dynamic.',practiceConnection:'A nutrition professional can explain why bone health involves adequate substrate and whole-body regulation, while diagnosis and treatment remain clinical responsibilities.',activity:{prompt:'Which skeletal role most directly connects bone to blood-cell production?',options:[{text:'Hematopoiesis in red marrow',correct:true,feedback:'Correct. Red marrow is a major site of blood-cell formation.'},{text:'Fat storage in yellow marrow',correct:false,feedback:'Yellow marrow stores fat; it is not the primary answer for blood-cell formation.'},{text:'Articulation at a joint',correct:false,feedback:'Joints enable movement but do not describe hematopoiesis.'}]}},
      {id:'l7-m2',title:'Build, maintain, resorb',highYield:'Osteoblasts deposit bone, osteocytes maintain it, and osteoclasts resorb it during remodeling.',teaching:[
        'Bone formation begins with osteoblasts. As the surrounding matrix matures, many become osteocytes housed in small spaces called lacunae. Osteoclasts remove bone, which is essential for shaping, repair and mineral regulation rather than simply being destructive.',
        'Intramembranous ossification builds bone within connective membranes, especially in the skull. Endochondral ossification replaces a cartilage model and forms most other bones. Remodeling continues after growth has ended and responds to mechanical load and hormonal signals.'
      ],keyPoints:['Osteoblast = deposition.','Osteocyte = mature maintenance cell.','Osteoclast = resorption.','Intramembranous and endochondral ossification start from different templates.'],visual:{title:'Remodeling cycle',kind:'sequence',items:[{label:'Deposit',detail:'Osteoblast lays matrix'},{label:'Maintain',detail:'Osteocyte monitors local tissue'},{label:'Resorb',detail:'Osteoclast removes matrix'},{label:'Renew',detail:'New matrix replaces remodeled area'}]},mnemonic:{title:'BLC',cue:'Builders · Lodgers · Clean-up',explanation:'Blasts build, cytes live in the matrix, clasts clear bone.'},goodToKnow:'Parathyroid hormone and calcitonin participate in blood-calcium regulation; bone is one part of that larger system.',practiceConnection:'Calcium and vitamin D matter to bone biology, but a dietary history alone cannot determine bone density or fracture risk.',activity:{prompt:'Which pairing is accurate?',options:[{text:'Osteoclast — bone resorption',correct:true,feedback:'Correct. Osteoclasts remove mineralized matrix during remodeling.'},{text:'Osteocyte — first cartilage model',correct:false,feedback:'A cartilage model belongs to endochondral ossification; osteocytes are mature bone cells.'},{text:'Osteoblast — mature cell in a lacuna',correct:false,feedback:'A mature bone cell in a lacuna is an osteocyte.'}]}}
    ]},
    {id:'bone-architecture',title:'Read bone architecture',summary:'Move from the osteon to whole-bone shape and marrow.',moments:[
      {id:'l7-m3',title:'Compact and spongy bone',highYield:'Compact bone is organized into osteons; spongy bone forms trabeculae around marrow spaces.',teaching:[
        'An osteon is the repeating structural unit of compact bone. A central canal carries vessels, concentric lamellae form rings, osteocytes occupy lacunae, and canaliculi create tiny communication routes through the hard matrix.',
        'Spongy or cancellous bone is arranged as a lattice of trabeculae. Its spaces contain marrow, and its architecture places material along lines of stress without making the bone solid throughout. Compact and spongy tissue therefore solve different mechanical problems.'
      ],keyPoints:['Central canal carries vessels.','Lamellae are concentric layers.','Lacunae house osteocytes.','Canaliculi connect spaces.','Trabeculae form the spongy lattice.'],visual:{title:'From center outward',kind:'rings',items:[{label:'Central canal',detail:'Vessels and nerves'},{label:'Lamellae',detail:'Concentric matrix rings'},{label:'Lacunae',detail:'Osteocyte spaces'},{label:'Canaliculi',detail:'Microscopic connecting channels'}]},mnemonic:{title:'CLLC',cue:'Canal · Lamellae · Lacunae · Canaliculi',explanation:'Walk outward from an osteon’s center.'},goodToKnow:'Bone looks solid macroscopically, yet microscopic channels keep living cells supplied.',practiceConnection:'Red-marrow distribution changes with age, which is why “bone marrow” is not a single uniform tissue throughout the skeleton.',activity:{prompt:'Where would you expect to find an osteocyte?',options:[{text:'Inside a lacuna',correct:true,feedback:'Correct. Osteocytes occupy lacunae in mineralized bone.'},{text:'Inside the central canal',correct:false,feedback:'The central canal primarily contains vessels and nerves.'},{text:'Only in yellow marrow',correct:false,feedback:'Yellow marrow stores fat; it is not the location of osteocytes.'}]}},
      {id:'l7-m4',title:'Long bones and shape classes',highYield:'A long bone has a shaft, ends, coverings and a marrow cavity; “long” describes shape, not absolute size.',teaching:[
        'The diaphysis is the shaft of a long bone, the epiphyses are its ends, and the metaphyses are transition regions. Periosteum covers the outer surface except at articular cartilage, while endosteum lines internal surfaces. The medullary cavity occupies the shaft.',
        'Bones are also classified as long, short, flat, irregular or sesamoid. Flat bones provide broad protection or muscle attachment; irregular bones have complex shapes; sesamoid bones develop within tendons. Classification helps predict form and function.'
      ],keyPoints:['Diaphysis = shaft.','Epiphysis = end.','Periosteum is external; endosteum is internal.','Patella is a sesamoid bone.'],visual:{title:'Long-bone route',kind:'label-strip',items:[{label:'Epiphysis',detail:'Expanded end'},{label:'Metaphysis',detail:'Transition/growth region'},{label:'Diaphysis',detail:'Shaft and medullary cavity'},{label:'Periosteum',detail:'Fibrovascular outer covering'}]},mnemonic:{title:'DME',cue:'Diaphysis = Drive shaft; Metaphysis = Middle transition; Epiphysis = End',explanation:'Use position to retrieve each name.'},goodToKnow:'The femur is long, but tiny phalanges are also classified as long bones because of their proportions.',practiceConnection:'Mechanical loading is one influence on remodeling; it should not be reduced to a promise that one food or exercise prevents every bone problem.',activity:{prompt:'Which structure is the shaft of a long bone?',options:[{text:'Diaphysis',correct:true,feedback:'Correct. The diaphysis is the elongated shaft.'},{text:'Epiphysis',correct:false,feedback:'The epiphysis is an end of the bone.'},{text:'Lacuna',correct:false,feedback:'A lacuna is a microscopic space housing an osteocyte.'}]}}
    ]},
    {id:'axial',title:'Map the axial skeleton',summary:'Organize skull, vertebral column and thorax around protection.',moments:[
      {id:'l7-m5',title:'Cranium, face and openings',highYield:'Cranial bones protect the brain; facial bones shape the face and support the air and food passages.',teaching:[
        'The axial skeleton begins with the skull. Cranial bones include the frontal, parietal, temporal, occipital, sphenoid and ethmoid bones. The sphenoid spans the cranial floor and helps bind several cranial bones together. Facial bones include the maxillae, zygomatic bones and mandible.',
        'Openings and processes reveal function. The foramen magnum in the occipital bone transmits the spinal cord, while condyles articulate with the first cervical vertebra. Sutures are fibrous joints that unite skull bones.'
      ],keyPoints:['Cranial and facial bones have different organizing roles.','Mandible forms the lower jaw.','Sphenoid anchors across the cranial floor.','Foramen magnum connects cranial and vertebral spaces.'],visual:{title:'Skull landmarks',kind:'map',items:[{label:'Frontal',detail:'Forehead and anterior cranial roof'},{label:'Occipital',detail:'Posterior skull and foramen magnum'},{label:'Sphenoid',detail:'Central cranial-floor anchor'},{label:'Mandible',detail:'Movable lower jaw'}]},mnemonic:{title:'FOSTEP',cue:'Frontal · Occipital · Sphenoid · Temporal · Ethmoid · Parietal',explanation:'A compact cue for the main cranial-bone set.'},goodToKnow:'The hyoid is part of the axial skeleton but does not articulate directly with another bone.',practiceConnection:'Knowing skull landmarks helps a learner interpret terms in swallowing, dental and neurological discussions without diagnosing injury.',activity:{prompt:'Which opening carries the spinal cord through the skull?',options:[{text:'Foramen magnum',correct:true,feedback:'Correct. It is the large opening in the occipital bone.'},{text:'Medullary cavity',correct:false,feedback:'That is an internal cavity of a long bone.'},{text:'Acetabulum',correct:false,feedback:'The acetabulum is the hip socket.'}]}},
      {id:'l7-m6',title:'Vertebral column and thorax',highYield:'The vertebral column protects the spinal cord; ribs and sternum protect thoracic organs and support breathing.',teaching:[
        'The vertebral column is organized into cervical, thoracic, lumbar, sacral and coccygeal regions. The atlas supports the skull and the axis permits rotation. Normal curves distribute load; exaggerated or lateral curves are described with specific terms such as kyphosis, lordosis and scoliosis.',
        'The thoracic cage includes thoracic vertebrae, ribs and sternum. True ribs attach directly to the sternum through costal cartilage, false ribs attach indirectly, and floating ribs lack anterior attachment. The sternum includes the manubrium, body and xiphoid process.'
      ],keyPoints:['Seven cervical, twelve thoracic and five lumbar vertebrae precede the fused regions.','Atlas and axis have specialized roles.','True ribs attach directly; floating ribs do not attach anteriorly.','The sternum is the breastbone.'],visual:{title:'Axial stack',kind:'vertical',items:[{label:'Cervical',detail:'Neck; C1–C7'},{label:'Thoracic',detail:'Rib-bearing; T1–T12'},{label:'Lumbar',detail:'Lower back; L1–L5'},{label:'Sacrum/coccyx',detail:'Fused terminal regions'}]},mnemonic:{title:'Breakfast schedule',cue:'7 · 12 · 5',explanation:'Seven cervical, twelve thoracic and five lumbar—breakfast at 7, lunch at 12, dinner at 5.'},goodToKnow:'“True” and “false” describe rib attachment patterns, not whether a rib is complete or functional.',practiceConnection:'Posture and curvature terms describe anatomy; persistent pain or suspected injury requires appropriate clinical assessment.',activity:{prompt:'Which region articulates with ribs?',options:[{text:'Thoracic vertebrae',correct:true,feedback:'Correct. Ribs articulate with thoracic vertebrae.'},{text:'Cervical vertebrae',correct:false,feedback:'Cervical vertebrae form the neck.'},{text:'Coccygeal vertebrae',correct:false,feedback:'The coccyx is the terminal fused region.'}]}}
    ]},
    {id:'appendicular',title:'Use the appendicular skeleton',summary:'Connect girdles and limbs to movement, load and practical bone health.',moments:[
      {id:'l7-m7',title:'Girdles and limbs',highYield:'The pectoral and pelvic girdles attach the upper and lower limbs to the axial skeleton.',teaching:[
        'The pectoral girdle consists of clavicles and scapulae. It prioritizes mobility, giving the upper limb a wide range of movement. The upper limb continues through humerus, radius and ulna to carpals, metacarpals and phalanges.',
        'The pelvic girdle forms a stronger weight-bearing ring. Each hip bone is formed by the ilium, ischium and pubis; the acetabulum receives the femoral head. The lower limb continues through femur, patella, tibia and fibula to tarsals, metatarsals and phalanges.'
      ],keyPoints:['Pectoral girdle favors mobility.','Pelvic girdle favors stability and weight transfer.','Radius/ulna are forearm bones.','Tibia/fibula are leg bones.','Carpals are wrist; tarsals are ankle/foot.'],visual:{title:'Paired pathways',kind:'compare',items:[{label:'Upper limb',detail:'Scapula → humerus → radius/ulna → carpals'},{label:'Lower limb',detail:'Hip → femur → tibia/fibula → tarsals'}]},mnemonic:{title:'Car before tar',cue:'Carpals = hands; tarsals = feet',explanation:'A car is handled with the hands; tar is under the feet.'},goodToKnow:'The patella is the largest sesamoid bone and develops within the quadriceps tendon.',practiceConnection:'Bone names support accurate movement and injury communication but do not replace assessment of pain, swelling or function.',activity:{prompt:'Which structure receives the head of the femur?',options:[{text:'Acetabulum',correct:true,feedback:'Correct. It is the socket on the hip bone.'},{text:'Glenoid fossa',correct:false,feedback:'The glenoid fossa receives the humeral head at the shoulder.'},{text:'Foramen magnum',correct:false,feedback:'That opening is in the occipital bone.'}]}},
      {id:'l7-m8',title:'Bone health is a system question',highYield:'Bone strength reflects matrix, cells, hormones, nutrients, load and time—not one nutrient in isolation.',teaching:[
        'Calcium and phosphorus contribute to mineralized matrix, while vitamin D supports calcium absorption. Protein supplies matrix components. Hormones help regulate deposition and release, and mechanical load influences remodeling. Adequacy across these factors matters more than a single “bone food.”',
        'Disorders illustrate different mechanisms: rickets and osteomalacia involve impaired mineralization, osteoporosis involves reduced bone mass and altered structure, and Paget disease involves disordered remodeling. A fracture is a break in bone or associated cartilage and requires clinical care.'
      ],keyPoints:['Mineralization and remodeling are different processes.','Vitamin D supports calcium handling.','Osteoporosis is not simply “low calcium.”','Fracture, rickets and Paget disease describe different problems.'],visual:{title:'Bone maintenance web',kind:'network',items:[{label:'Matrix',detail:'Collagen-rich framework plus mineral'},{label:'Cells',detail:'Deposit, maintain and resorb'},{label:'Signals',detail:'Hormonal regulation'},{label:'Inputs',detail:'Nutrients and mechanical load'},{label:'Time',detail:'Growth, aging and repair'}]},mnemonic:{title:'MINDS',cue:'Matrix · Inputs · load · endocrine signals · time',explanation:'Bone health emerges from interacting influences.'},goodToKnow:'An adult can have adequate current intake yet still require assessment for bone-density or fracture concerns.',practiceConnection:'Nutrition counselling can support adequate intake and feasible habits, while risk evaluation, diagnosis and treatment belong with qualified clinicians.',activity:{prompt:'Which statement best reflects bone maintenance?',options:[{text:'It depends on interacting cellular, nutritional, hormonal and mechanical factors.',correct:true,feedback:'Correct. Bone is maintained by an integrated system.'},{text:'It is determined by calcium intake alone.',correct:false,feedback:'Calcium matters, but bone maintenance is not a one-nutrient process.'},{text:'It stops when height growth ends.',correct:false,feedback:'Remodeling continues throughout life.'}]}}
    ]}
  ],
  caseStudy:{title:'From a fall to a systems explanation',scenario:'An older adult reports a recent fall and asks whether drinking more milk alone will “rebuild” every weak bone.',prompts:['Name the skeletal functions relevant to the fall.','Explain remodeling using osteoblasts and osteoclasts.','Identify the limits of a one-food explanation.','State which concerns require clinical assessment rather than nutrition education alone.'],takeaway:'Use anatomy to explain the system, support adequate nutrition without promises, and keep fracture and bone-density assessment within clinical care.'},
  recap:['The skeleton supports, protects, moves, forms blood cells and stores minerals.','Osteoblasts deposit, osteocytes maintain and osteoclasts resorb bone.','Compact bone is organized into osteons; spongy bone into trabeculae.','Axial structures protect the central axis; appendicular structures enable limb movement.','Long-bone terms describe shaft, ends, coverings and cavity.','Bone health integrates nutrients, hormones, load and time.'],
  flashcards:[
    {front:'Osteoblast',back:'Bone-forming cell that deposits matrix.',tag:'cells'},{front:'Osteoclast',back:'Large cell that resorbs bone during remodeling.',tag:'cells'},{front:'Osteocyte',back:'Mature bone cell located in a lacuna.',tag:'cells'},{front:'Osteon',back:'Central canal plus concentric lamellae of compact bone.',tag:'microanatomy'},{front:'Canaliculi',back:'Tiny channels connecting lacunae with each other and the central canal.',tag:'microanatomy'},{front:'Diaphysis',back:'Shaft of a long bone.',tag:'long bone'},{front:'Epiphysis',back:'Expanded end of a long bone.',tag:'long bone'},{front:'Axial skeleton',back:'Skull, vertebral column and thoracic cage.',tag:'organization'},{front:'Appendicular skeleton',back:'Girdles and limbs.',tag:'organization'},{front:'Foramen magnum',back:'Large occipital opening for the spinal cord.',tag:'skull'},{front:'Acetabulum',back:'Hip socket that receives the femoral head.',tag:'pelvis'},{front:'Hematopoiesis',back:'Formation of blood cells, largely in red marrow.',tag:'function'}
  ],
  practice:[
    {prompt:'Contrast intramembranous and endochondral ossification.',answer:'Intramembranous bone develops within connective membrane; endochondral bone replaces a cartilage model.',rationale:'The starting template distinguishes the two processes.',tag:'formation'},{prompt:'Trace nutrients to an osteocyte in compact bone.',answer:'Vessels in a central canal supply fluid that moves through canaliculi toward lacunae.',rationale:'This explains how cells survive inside hard matrix.',tag:'microanatomy'},{prompt:'Why is the patella a sesamoid bone?',answer:'It develops within a tendon rather than being classified by length.',rationale:'Sesamoid describes developmental location.',tag:'classification'},{prompt:'Name the five skeletal functions.',answer:'Support, protection, leverage for movement, blood-cell formation and storage of minerals/fat.',rationale:'These functions organize the whole chapter.',tag:'function'},{prompt:'Which cell would be active during bone resorption?',answer:'Osteoclast.',rationale:'Resorption is the osteoclast’s defining role.',tag:'cells'},{prompt:'Differentiate periosteum and endosteum.',answer:'Periosteum covers the external bone surface; endosteum lines internal surfaces.',rationale:'The names describe outer versus inner coverings.',tag:'long bone'},{prompt:'Place sternum, femur and scapula into axial or appendicular divisions.',answer:'Sternum is axial; femur and scapula are appendicular.',rationale:'Girdles and limbs are appendicular.',tag:'organization'},{prompt:'Explain true versus floating ribs.',answer:'True ribs attach directly to sternum through cartilage; floating ribs lack anterior attachment.',rationale:'The labels refer to attachment pattern.',tag:'thorax'},{prompt:'Why can bone affect blood calcium?',answer:'Mineral is stored in matrix and released or deposited under cellular and hormonal regulation.',rationale:'Bone is a regulated reservoir.',tag:'integration'},{prompt:'Why is “more calcium fixes every bone problem” incomplete?',answer:'Bone strength also depends on matrix, cells, vitamin D, hormones, load, health history and time.',rationale:'A single input cannot explain an integrated tissue.',tag:'practice'}
  ]
};
